import{_ as a,o as t,c as d,a3 as o}from"./chunks/framework.B8xISX-C.js";const m=JSON.parse('{"title":"armor","description":"","frontmatter":{},"headers":[],"relativePath":"reference/armor.md","filePath":"reference/armor.md"}'),r={name:"reference/armor.md"};function s(c,e,n,i,l,p){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="armor" tabindex="-1">armor <a class="header-anchor" href="#armor" aria-label="Permalink to &quot;armor&quot;">​</a></h1><p>An armour tier, unlocked by an application (<code>app</code>).</p><p>A mod adds records in <code>records/armor/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;armor&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>armor</code>. Schema: <a href="/carina-mod-template/schemas/records/armor.schema.json">armor records schema</a>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-app" class="field-name"><code>app</code></span><a class="field-link" href="#f-app" aria-label="Link to app">#</a></td><td>snake_case key</td><td>yes</td><td></td></tr><tr><td><span id="f-mult" class="field-name"><code>mult</code></span><a class="field-link" href="#f-mult" aria-label="Link to mult">#</a></td><td>integer &gt;= 1</td><td>yes</td><td></td></tr><tr><td><span id="f-troopBonus" class="field-name"><code>troopBonus</code></span><a class="field-link" href="#f-troopBonus" aria-label="Link to troopBonus">#</a></td><td>integer &gt;= 0</td><td>yes</td><td></td></tr><tr><td><span id="f-strategicHp" class="field-name"><code>strategicHp</code></span><a class="field-link" href="#f-strategicHp" aria-label="Link to strategicHp">#</a></td><td>integer &gt;= 0</td><td>yes</td><td></td></tr><tr><td><span id="f-negatesAp" class="field-name"><code>negatesAp</code></span><a class="field-link" href="#f-negatesAp" aria-label="Link to negatesAp">#</a></td><td>true or false</td><td>yes</td><td></td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr></tbody></table><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><p>Nothing else: the record works on its own.</p><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>The ship designer, starting designs and refits take the strongest known armour by its stats: <code>mult</code>, then <code>strategicHp</code>, then the later record on a full tie. A weaker mod tier is never picked over a stronger one the empire knows.</p><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>app</code>, <code>mult</code>, <code>nameKey</code>, <code>negatesAp</code>, <code>strategicHp</code>, <code>troopBonus</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: none (no list fields)</li></ul>',13)])])}const f=a(r,[["render",s]]);export{m as __pageData,f as default};
